    assert(reversed_multiple[1] == 'b');
    assert(reversed_multiple[2] == 'a');
    
    // Test palindrome
    let mut palindrome = Vec::new();
    palindrome.push('r');
    palindrome.push('a');
    palindrome.push('c');
    palindrome.push('e');
